import{_ as e,a as t}from"./chunks/stand-bumper-2.dLU7JT00.js";import{_ as r,o,c as i,a5 as n}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"스탠드 및 범퍼 교체","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/maintenance/bumper.md","filePath":"ko/manual/maintenance/bumper.md","lastUpdated":1785806767000}'),m={name:"ko/manual/maintenance/bumper.md"};function l(s,a,d,h,_,c){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="스탠드-및-범퍼-교체" tabindex="-1">스탠드 및 범퍼 교체 <a class="header-anchor" href="#스탠드-및-범퍼-교체" aria-label="Permalink to &quot;스탠드 및 범퍼 교체&quot;">​</a></h1><p>RBQ10이 대기 자세(앉은 자세)일 때 본체를 지지하는 스탠드와, 로봇이 넘어질 때 충격을 흡수하는 전면/후면 범퍼는 사용에 따라 마모되므로 교체가 필요합니다. 교체 방법은 다음과 같으니 필요 시 참고하세요.</p><h2 id="스탠드-교체" tabindex="-1">스탠드 교체 <a class="header-anchor" href="#스탠드-교체" aria-label="Permalink to &quot;스탠드 교체&quot;">​</a></h2><p>RBQ10의 스탠드는 M4x10mm 육각 볼트와 M4 평와셔로 구성되어 있습니다. 분해 중 부품이 분실된 경우, 동일 규격의 부품을 구매하여 사용할 수 있습니다.</p><figure><img src="'+e+'" alt="스탠드·범퍼 교체 1"></figure><h3 id="_1단계-3mm-육각-렌치를-사용하여-볼트를-풉니다" tabindex="-1">1단계. 3mm 육각 렌치를 사용하여 볼트를 풉니다. <a class="header-anchor" href="#_1단계-3mm-육각-렌치를-사용하여-볼트를-풉니다" aria-label="Permalink to &quot;1단계. 3mm 육각 렌치를 사용하여 볼트를 풉니다.&quot;">​</a></h3><h3 id="_2단계-우레탄-스탠드를-빼내고-새-부품으로-교체합니다" tabindex="-1">2단계. 우레탄 스탠드를 빼내고 새 부품으로 교체합니다. <a class="header-anchor" href="#_2단계-우레탄-스탠드를-빼내고-새-부품으로-교체합니다" aria-label="Permalink to &quot;2단계. 우레탄 스탠드를 빼내고 새 부품으로 교체합니다.&quot;">​</a></h3><h3 id="_3단계-볼트를-체결합니다-볼트-나사산에-락타이트-243을-도포하세요" tabindex="-1">3단계. 볼트를 체결합니다. (볼트 나사산에 락타이트 243을 도포하세요) <a class="header-anchor" href="#_3단계-볼트를-체결합니다-볼트-나사산에-락타이트-243을-도포하세요" aria-label="Permalink to &quot;3단계. 볼트를 체결합니다. (볼트 나사산에 락타이트 243을 도포하세요)&quot;">​</a></h3><h2 id="전면-및-후면-범퍼" tabindex="-1">전면 및 후면 범퍼 <a class="header-anchor" href="#전면-및-후면-범퍼" aria-label="Permalink to &quot;전면 및 후면 범퍼&quot;">​</a></h2><figure><img src="'+t+'" alt="스탠드·범퍼 교체 2"></figure><p>M3x10mm 볼트 3세트와 M4 평와셔로 범퍼가 로봇에 고정되어 있습니다.</p><p>2.5mm 육각 렌치를 사용하여 볼트를 풀어줍니다.</p>',12)])])}const b=r(m,[["render",l]]);export{f as __pageData,b as default};
